"use client";
import { Fragment, useEffect, useMemo, useRef, useState } from "react";
import SiteEditor from "@/components/SiteEditor";
import { normalizeSite, DEFAULT_TEXT, DEFAULT_IMAGE, type SiteConfig, type Section } from "@/lib/site";

/* ========= Helpers ========= */
const fmtDate=(d:any)=> d? new Date(d).toLocaleDateString("ar-EG",{year:"numeric",month:"short",day:"numeric"}) : "بدون تاريخ انتهاء";
function drivePreview(url:string){ const m=(url||"").match(/drive\.google\.com\/file\/d\/([^/]+)/); return m?`https://drive.google.com/file/d/${m[1]}/preview`:url; }
function driveDownload(url:string){ const m=(url||"").match(/drive\.google\.com\/file\/d\/([^/]+)/); return m?`https://drive.google.com/uc?export=download&id=${m[1]}`:url; }
function codeStatus(c:any){ if(c.expiresAt && new Date(c.expiresAt)<new Date()) return {t:"منتهي",cls:"bg-red-100 text-red-700"}; if(!c.isActive) return {t:"غير فعال",cls:"bg-slate-200 text-slate-700"}; if((c.usedCount||0)>=(c.maxUses||1)) return {t:"مستنفد",cls:"bg-amber-100 text-amber-800"}; return {t:"فعال",cls:"bg-emerald-100 text-emerald-700"}; }
async function api(path:string,body?:any){ const r=await fetch(path,{method:body?"POST":"GET",headers:{"Content-Type":"application/json"},body:body?JSON.stringify(body):undefined}); const j=await r.json().catch(()=>({})); if(!r.ok) throw new Error(j.error||"حدث خطأ"); return j; }
function downloadText(name:string,text:string,type="text/plain"){ const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([text],{type})); a.download=name; a.click(); }

/* ========= Protected YouTube Player ========= */
function ProtectedPlayer({lesson,userEmail,onComplete}:{lesson:any,userEmail?:string,onComplete:()=>void}){
  const ref=useRef<HTMLIFrameElement>(null); const wrapRef=useRef<HTMLDivElement>(null);
  const [playing,setPlaying]=useState(false); const [seconds,setSeconds]=useState(0); const [speed,setSpeed]=useState(1);
  useEffect(()=>{ setPlaying(false); setSeconds(0); },[lesson?.id]);
  useEffect(()=>{ if(!playing) return; const t=setInterval(()=>setSeconds(s=>s+1),1000/speed); return ()=>clearInterval(t); },[playing,speed]);
  useEffect(()=>{ const block=(e:KeyboardEvent)=>{ if((e.ctrlKey||e.metaKey)&&["s","p","u"].includes(e.key.toLowerCase())) e.preventDefault(); if(e.key==="F12") e.preventDefault(); }; window.addEventListener("keydown",block); return ()=>window.removeEventListener("keydown",block); },[]);
  const cmd=(func:string,args:any[]=[] )=>{ ref.current?.contentWindow?.postMessage(JSON.stringify({event:"command",func,args}),"*"); };
  const toggle=()=>{ if(playing){cmd("pauseVideo"); setPlaying(false);} else {cmd("playVideo"); setPlaying(true);} };
  const seek=(diff:number)=>{ const ns=Math.max(0,seconds+diff); setSeconds(ns); cmd("seekTo",[ns,true]); };
  const fullscreen=()=>{ if(document.fullscreenElement) document.exitFullscreen(); else wrapRef.current?.requestFullscreen?.(); };
  const changeSpeed=(v:number)=>{ setSpeed(v); cmd("setPlaybackRate",[v]); };
  if(!lesson?.youtubeId) return <div className="aspect-video bg-slate-900 text-white grid place-items-center rounded-2xl p-6 text-center">🔒 هذا الدرس محمي — أدخل الكود لفتح الفيديو</div>;
  return (
    <div ref={wrapRef} className="bg-black rounded-2xl overflow-hidden select-none player-shell" onContextMenu={e=>e.preventDefault()}>
      <div className="relative aspect-video bg-black">
        <iframe ref={ref} key={lesson.id} src={`https://www.youtube-nocookie.com/embed/${lesson.youtubeId}?enablejsapi=1&rel=0&modestbranding=1&playsinline=1&controls=0&disablekb=1&fs=0&iv_load_policy=3`} className="absolute inset-0 w-full h-full pointer-events-none" allow="autoplay; encrypted-media; picture-in-picture" title={lesson.title}/>
        {/* Overlay يمنع لمس الفيديو ونسخ الرابط والسحب للخارج */}
        <div className="absolute inset-0 cursor-pointer" onClick={toggle} onContextMenu={e=>e.preventDefault()} onDragStart={e=>e.preventDefault()}>
          {!playing && <div className="absolute inset-0 grid place-items-center bg-black/40"><span className="w-20 h-20 rounded-full bg-teal-600 text-white grid place-items-center text-3xl shadow-2xl">▶</span></div>}
          <div className="watermark absolute top-4 left-4 text-white/30 text-xs rotate-[-8deg]">{userEmail||"منصة مستر محمد هلال ©"}</div>
          <div className="watermark absolute bottom-10 right-4 text-white/20 text-xs">🔒 مشغل محمي — منصة مستر محمد هلال</div>
        </div>
        <div className="absolute top-0 inset-x-0 p-3 bg-black/60 text-white text-sm flex justify-between pointer-events-none"><span className="font-bold truncate">{lesson.title}</span><span className="bg-red-600 px-2 py-0.5 rounded text-xs shrink-0">محمي 🔒</span></div>
      </div>
      {/* Custom Controls - كبيرة ومناسبة للمس */}
      <div className="bg-slate-950 text-white p-3 flex flex-wrap items-center gap-2" dir="ltr">
        <button onClick={toggle} className="bg-teal-600 px-5 py-3 rounded-xl font-bold min-w-[92px]">{playing?"⏸ إيقاف":"▶ تشغيل"}</button>
        <button onClick={()=>seek(-10)} className="bg-white/10 px-4 py-3 rounded-xl">⏪ 10-</button>
        <button onClick={()=>seek(10)} className="bg-white/10 px-4 py-3 rounded-xl">10+ ⏩</button>
        <span className="text-sm bg-white/10 px-3 py-2 rounded-lg">{Math.floor(seconds/60)}:{String(seconds%60).padStart(2,"0")} / {lesson.duration||"--"}</span>
        <select value={speed} onChange={e=>changeSpeed(Number(e.target.value))} className="bg-white/10 rounded-lg px-2 py-3 text-white [&>option]:text-black"><option value={0.5}>0.5x</option><option value={1}>1x</option><option value={1.25}>1.25x</option><option value={1.5}>1.5x</option><option value={2}>2x</option></select>
        <button onClick={fullscreen} className="bg-white/10 px-4 py-3 rounded-xl mr-auto">⛶ ملء الشاشة</button>
        <button onClick={onComplete} className="bg-emerald-600 px-4 py-3 rounded-xl font-bold">✓ إتمام الدرس</button>
      </div>
      <p className="text-[11px] text-slate-400 px-3 py-2 bg-slate-950">🛡️ حماية: ممنوع الكليك يمين • الروابط مخفية • طبقة حماية فوق الفيديو • علامة مائية بحسابك • الاختصارات معطلة أثناء المشاهدة</p>
    </div>
  );
}

/* ========= Main App ========= */
type View="home"|"course"|"profile"|"favorites"|"history"|"admin";
export default function Page(){
  const [data,setData]=useState<any>(null); const [admin,setAdmin]=useState<any>(null);
  const [view,setView]=useState<View>("home"); const [selected,setSelected]=useState<any>(null); const [lesson,setLesson]=useState<any>(null);
  const [q,setQ]=useState(""); const [cat,setCat]=useState("الكل"); const [dark,setDark]=useState(false);
  const [modal,setModal]=useState<string>(""); const [toast,setToast]=useState("");
  const [authForm,setAuthForm]=useState({name:"",email:"",password:""}); const [devPw,setDevPw]=useState("");
  const [forgotTemp,setForgotTemp]=useState(""); const [teacherForm,setTeacherForm]=useState({name:"",email:"",subject:"",message:""});
  const [codeInput,setCodeInput]=useState(""); const [qrCourse,setQrCourse]=useState<any>(null);
  const [adminTab,setAdminTab]=useState("dashboard");
  const [courseForm,setCourseForm]=useState<any>({title:"",description:"",image:"",teacherName:"",category:"عام",level:"جميع المستويات",isPublished:true});
  const [lessonForm,setLessonForm]=useState<any>({type:"video",title:"",description:"",youtubeId:"",url:"",duration:"",isFree:false,isProtected:true,allowDownload:false,courseId:"",moduleId:""});
  const [editLessonId,setEditLessonId]=useState<any>(null);
  const [moduleTitle,setModuleTitle]=useState(""); const [codeGen,setCodeGen]=useState<any>({lessonId:"",count:10,maxUses:1,expiresAt:"",customCode:""});
  const [newUser,setNewUser]=useState({name:"",email:"",password:"",role:"teacher"});
  const [importCsv,setImportCsv]=useState(""); const [devChange,setDevChange]=useState({current:"",next:""});
  const [notifyForm,setNotifyForm]=useState({title:"",body:""}); const [backupData,setBackupData]=useState<any>(null);
  const [wizard,setWizard]=useState<any>({title:"",description:"",image:"",teacherName:"",category:"عام",modules:[{title:"الوحدة الأولى",lessons:[{type:"video",title:"",youtubeId:"",url:"",isFree:true,isProtected:false,duration:""}]}]});
  const [searchAdmin,setSearchAdmin]=useState("");
  const dragId=useRef<any>(null);

  const showToast=(m:string)=>{ setToast(m); setTimeout(()=>setToast(""),3500); };
  const load=async()=>{ try{ const d=await api("/api/platform"); setData(d); if(d.isDev){ try{ setAdmin(await api("/api/admin"+(searchAdmin?`?q=${encodeURIComponent(searchAdmin)}`:""))); }catch{} } }catch(e:any){ showToast(e.message); } };
  useEffect(()=>{ load(); const t=localStorage.getItem("theme"); if(t==="dark"){setDark(true); document.documentElement.classList.add("dark");} const sw=()=>{}; if("serviceWorker" in navigator){ navigator.serviceWorker.register("/sw.js").catch(()=>{}); } },[]);
  useEffect(()=>{ if(data?.isDev) api("/api/admin"+(searchAdmin?`?q=${encodeURIComponent(searchAdmin)}`:"")).then(setAdmin).catch(()=>{}); },[searchAdmin,data?.isDev]);

  const site:SiteConfig=data?.site||normalizeSite({});
  const tx=(k:string):string=>site.texts[k] ?? DEFAULT_TEXT[k] ?? "";
  const im=(k:string):string=>site.images[k] || DEFAULT_IMAGE[k] || "";
  const user=data?.user; const courses=data?.courses||[]; const lessons=data?.lessons||[]; const modules=data?.modules||[];
  const cats=["الكل",...Array.from(new Set(courses.map((c:any)=>c.category))) as string[]];
  const filtered=courses.filter((c:any)=>(cat==="الكل"||c.category===cat)&&(c.title.includes(q)||c.description.includes(q)||c.teacherName.includes(q)));
  const progressOf=(courseId:number)=>{ const ls=lessons.filter((l:any)=>l.courseId===courseId&&l.type==="video"); if(!ls.length) return 0; const done=(data?.progress||[]).filter((p:any)=>p.courseId===courseId&&p.isCompleted).length; return Math.round(done/Math.max(1,ls.length)*100); };
  const counts=(courseId:number)=>{ const ls=lessons.filter((l:any)=>l.courseId===courseId); return {v:ls.filter((l:any)=>l.type==="video").length,p:ls.filter((l:any)=>l.type==="pdf").length,l:ls.filter((l:any)=>l.type==="link").length,total:ls.length}; };
  const isFav=(id:number)=>(data?.favorites||[]).some((f:any)=>f.courseId===id);

  const openCourse=async(c:any)=>{ setSelected(c); setView("course"); const last=localStorage.getItem(`last-${c.id}`); const ls=lessons.filter((l:any)=>l.courseId===c.id); const first= last? ls.find((l:any)=>l.id===Number(last))||ls[0] : ls[0]; setLesson(first||null); api("/api/platform",{action:"view-course",courseId:c.id}).catch(()=>{}); window.scrollTo({top:0,behavior:"smooth"}); };
  const playLesson=async(l:any)=>{ setLesson(l); if(selected) localStorage.setItem(`last-${selected.id}`,String(l.id)); if(user&&l.unlocked){ try{ await api("/api/platform",{action:"progress",lessonId:l.id,courseId:l.courseId,completed:(data?.progress||[]).find((p:any)=>p.lessonId===l.id)?.isCompleted||false}); load(); }catch{} } if(!l.unlocked) setModal("code"); window.scrollTo({top:0,behavior:"smooth"}); };
  const toggleTheme=()=>{ const n=!dark; setDark(n); document.documentElement.classList.toggle("dark",n); localStorage.setItem("theme",n?"dark":"light"); };

  /* Auth actions */
  const doAuth=async(mode:string)=>{ try{ if(mode==="forgot"){ const r=await api("/api/auth",{action:"forgot",email:authForm.email}); showToast(r.message); return; } const r=await api("/api/auth",{action:mode,...authForm}); showToast(mode==="register"?"🎉 تم إنشاء الحساب بنجاح":"مرحباً بعودتك 👋"); setModal(""); load(); }catch(e:any){ showToast("❌ "+e.message); } };
  const doDevLogin=async()=>{ try{ await api("/api/auth",{action:"developer-login",password:devPw}); showToast("🔓 مرحباً بالمطور"); setModal(""); setView("admin"); load(); }catch(e:any){ showToast("❌ "+e.message); } };
  const logout=async()=>{ await api("/api/auth",{action:"logout"}); setView("home"); load(); showToast("تم تسجيل الخروج"); };
  const redeem=async()=>{ try{ await api("/api/platform",{action:"redeem",code:codeInput,lessonId:lesson.id}); showToast("✅ تم فتح الدرس بالكود بنجاح"); setModal(""); setCodeInput(""); load(); }catch(e:any){ showToast("❌ "+e.message); } };
  const saveSite=async(next:SiteConfig):Promise<SiteConfig>=>{ const r=await adminAct({action:"save-site",site:next},"✅ تم حفظ التعديلات ونشرها على الموقع"); return normalizeSite(r.site); };
  const uploadAsset=async(data:string,name:string):Promise<string>=>{ const r=await api("/api/admin",{action:"upload-asset",data,name}); return r.url as string; };
  const adminAct=async(body:any,msg="تم الحفظ ✅")=>{ try{ const r=await api("/api/admin",body); showToast(msg); load(); return r; }catch(e:any){ showToast("❌ "+e.message); throw e; } };

  if(!data) return <div className="min-h-screen grid place-items-center"><div className="text-center"><div className="text-6xl mb-3">🎓</div><p className="font-bold text-teal-700">جاري تحميل منصة مستر محمد هلال...</p></div></div>;

  const visibleSections=site.sections.filter(s=>s.visible);
  const sectionWrap=(sec:Section)=>`${sec.bg==="brand"?"bg-teal-800 text-white":sec.bg==="muted"?"bg-slate-100 dark:bg-slate-900/60":""} ${sec.align==="center"?"text-center":sec.align==="left"?"text-left":"text-right"} ${sec.width==="full"?"[&>*]:!max-w-none":""}`;
  const renderSection=(sec:Section)=>{
    const wrap=(inner:any)=><div key={sec.id} className={sectionWrap(sec)}>{inner}</div>;
    if(sec.type==="hero") return wrap(<>
        <section>
          <div className="max-w-7xl mx-auto px-4 py-10 grid md:grid-cols-2 gap-8 items-center">
            <div className={sec.reverse?"md:order-2":""}><span className="bg-white/15 px-3 py-1 rounded-full text-sm">{tx("hero.badge")}</span><h1 className="text-3xl md:text-5xl font-black leading-tight mt-4">{tx("hero.title").split("\n").map((l,i)=><Fragment key={i}>{i>0&&<br/>}{l}</Fragment>)}</h1><p className="text-teal-100 mt-3 leading-8">{tx("hero.subtitle")}</p>
            <div className="flex gap-2 mt-5 flex-wrap"><button onClick={()=>document.getElementById("courses")?.scrollIntoView({behavior:"smooth"})} className="bg-white text-teal-800 px-6 py-4 rounded-2xl font-black text-lg shadow">{tx("hero.ctaCourses")}</button><button onClick={()=>setModal("teacher")} className="bg-amber-500 px-6 py-4 rounded-2xl font-black text-lg">{tx("hero.ctaTeacher")}</button></div>
            <div className="grid grid-cols-4 gap-2 mt-6 text-center"><div className="bg-white/10 rounded-2xl p-3"><b className="text-xl">{courses.length}</b><span className="block text-xs">{tx("hero.statCourses")}</span></div><div className="bg-white/10 rounded-2xl p-3"><b className="text-xl">{lessons.filter((l:any)=>l.type==="video").length}</b><span className="block text-xs">{tx("hero.statVideos")}</span></div><div className="bg-white/10 rounded-2xl p-3"><b className="text-xl">{lessons.filter((l:any)=>l.type==="pdf").length}</b><span className="block text-xs">{tx("hero.statPdf")}</span></div><div className="bg-white/10 rounded-2xl p-3"><b className="text-xl">{lessons.reduce((a:any,l:any)=>a+(l.views||0),0)}</b><span className="block text-xs">{tx("hero.statViews")}</span></div></div></div>
            <img loading="lazy" src={im("heroImage")} alt={tx("brand.name")} className={`rounded-3xl shadow-2xl w-full h-72 object-cover ${sec.reverse?"md:order-1":""}`}/>
          </div>
        </section>

</>);
    if(sec.type==="continue") return wrap(<>
        {/* Continue watching */}
        {user && (data.history||[]).length>0 && <section className="max-w-7xl mx-auto px-4 pt-8"><h2 className="font-black text-xl mb-3">{tx("continue.title")}</h2><div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">{(data.history||[]).slice(0,8).map((h:any)=>{ const l=lessons.find((x:any)=>x.id===h.lessonId); const c=courses.find((x:any)=>x.id===h.courseId); if(!l) return null; return <button key={h.id} onClick={()=>{ if(c) openCourse(c); setTimeout(()=>playLesson(l),100); }} className="min-w-[240px] text-right bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-2xl p-4 shadow-sm"><b className="block truncate">{l.title}</b><span className="text-xs text-slate-500">{c?.title} • {fmtDate(h.watchedAt)}</span><span className="block mt-2 text-teal-700 font-bold text-sm">{tx("continue.cta")}</span></button>; })}</div></section>}

</>);
    if(sec.type==="courses") return wrap(<>
        <section id="courses" className="max-w-7xl mx-auto px-4 py-10">
          <div className="flex items-center justify-between flex-wrap gap-3"><div><h2 className="text-2xl font-black">{tx("courses.title")}</h2><p className="text-slate-500 text-sm">{tx("courses.subtitle")}</p></div>
          {data.isDev && <button onClick={()=>{setView("admin"); setAdminTab("create");}} className="bg-teal-700 text-white px-6 py-4 rounded-2xl font-black shadow">＋ إنشاء كورس جديد</button>}</div>
          <div className="flex gap-2 mt-5 overflow-x-auto no-scrollbar">{cats.map(c=><button key={c} onClick={()=>setCat(c)} className={`px-5 py-3 rounded-full font-bold whitespace-nowrap ${cat===c?"bg-teal-700 text-white":"bg-white dark:bg-slate-900 border dark:border-slate-800"}`}>{c}</button>)}</div>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5 mt-6">
            {filtered.map((c:any)=>{ const n=counts(c.id); const p=progressOf(c.id); return <article key={c.id} className="bg-white dark:bg-slate-900 rounded-3xl overflow-hidden border dark:border-slate-800 shadow-sm hover:shadow-xl transition fade-up">
              <div className="relative"><img loading="lazy" src={c.image||im("defaultCourseImage")} alt={c.title} className="h-48 w-full object-cover"/><span className="absolute top-3 right-3 bg-teal-700 text-white text-xs px-3 py-1 rounded-full">{c.category}</span><button onClick={async()=>{ if(!user){setModal("auth");return;} await api("/api/platform",{action:"favorite",courseId:c.id}); load(); }} className="absolute top-3 left-3 w-11 h-11 rounded-full bg-white shadow grid place-items-center text-lg">{isFav(c.id)?"❤️":"🤍"}</button></div>
              <div className="p-5"><h3 className="font-black text-lg leading-7">{c.title}</h3><p className="text-slate-500 text-sm mt-1 line-clamp-2 min-h-[40px]">{c.description}</p><p className="text-sm mt-2">👨‍🏫 {c.teacherName} • 📊 {c.level}</p>
              <div className="flex gap-2 text-xs mt-3 flex-wrap"><span className="bg-red-50 text-red-700 px-2 py-1 rounded-full">🎬 {n.v} فيديو</span><span className="bg-amber-50 text-amber-700 px-2 py-1 rounded-full">📄 {n.p} PDF</span><span className="bg-sky-50 text-sky-700 px-2 py-1 rounded-full">🔗 {n.l} رابط</span><span className="bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-full">👁️ {c.views||0}</span></div>
              {user && <div className="mt-3"><div className="flex justify-between text-xs font-bold"><span>تقدمك</span><span>{p}%</span></div><div className="h-2 bg-slate-100 dark:bg-slate-800 rounded-full mt-1 overflow-hidden"><div className="h-full bg-teal-600 rounded-full" style={{width:p+"%"}}/></div></div>}
              <div className="flex gap-2 mt-4"><button onClick={()=>openCourse(c)} className="flex-1 bg-teal-700 text-white py-3.5 rounded-xl font-black">{tx("courses.enter")}</button><button title="مشاركة" onClick={()=>{ navigator.clipboard.writeText(location.origin+"/?course="+c.id); showToast("🔗 تم نسخ رابط الكورس"); }} className="px-4 rounded-xl bg-slate-100 dark:bg-slate-800">↗️</button><button title="QR Code" onClick={()=>setQrCourse(c)} className="px-4 rounded-xl bg-slate-100 dark:bg-slate-800 font-bold">QR</button></div></div></article>; })}
          </div>
          {!filtered.length && <p className="text-center py-16 text-slate-500">{tx("courses.empty")}</p>}
        </section>

</>);
    if(sec.type==="notifications") return (data.notifications||[]).length>0 ? wrap(<div className="max-w-7xl mx-auto px-4 py-10"><h2 className="font-black text-xl mb-3">{tx("notifications.title")}</h2><div className="grid md:grid-cols-2 gap-3">{data.notifications.map((n:any)=><div key={n.id} className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-2xl p-4"><b>{n.title}</b><p className="text-sm text-slate-500 mt-1">{n.body}</p><span className="text-xs text-slate-400">{fmtDate(n.createdAt)}</span></div>)}</div></div>) : null;
    if(sec.type==="features") return wrap(<div className="max-w-7xl mx-auto px-4 py-12">{tx("features.title") && <h2 className="font-black text-xl mb-4">{tx("features.title")}</h2>}<div className="grid md:grid-cols-3 gap-4">{[[tx("feature1.icon"),tx("feature1.title"),tx("feature1.desc")],[tx("feature2.icon"),tx("feature2.title"),tx("feature2.desc")],[tx("feature3.icon"),tx("feature3.title"),tx("feature3.desc")]].map(([i,t,d]:any)=><div key={t} className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-6"><span className="text-3xl">{i}</span><h3 className="font-black mt-2">{t}</h3><p className="text-sm text-slate-500 leading-7 mt-1">{d}</p></div>)}</div></div>);
    if(sec.type==="custom"){
      const cb=sec.ref?site.customBlocks[sec.ref]:undefined;
      if(!cb) return null;
      return wrap(<div className="max-w-7xl mx-auto px-4 py-10 grid md:grid-cols-2 gap-8 items-center"><div className={sec.reverse?"md:order-2":""}><h2 className="text-2xl md:text-4xl font-black leading-tight">{cb.title}</h2><p className="mt-3 leading-8 whitespace-pre-line opacity-90">{cb.body}</p>{cb.buttonText&&cb.buttonUrl&&<a href={cb.buttonUrl} className="inline-block mt-5 bg-teal-700 text-white px-6 py-4 rounded-2xl font-black">{cb.buttonText}</a>}</div>{cb.image&&<img loading="lazy" src={cb.image} alt={cb.title} className={`rounded-3xl shadow-2xl w-full h-72 object-cover ${sec.reverse?"md:order-1":""}`}/>}</div>);
    }
    return null;
  };

  return (
    <div className="min-h-screen">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-white/95 dark:bg-slate-900/95 backdrop-blur border-b dark:border-slate-800 shadow-sm">
        <div className="max-w-7xl mx-auto px-3 py-3 flex items-center gap-2 flex-wrap">
          <button onClick={()=>setView("home")} className="flex items-center gap-2 font-black text-lg"><img src={im("logo")} alt={tx("brand.name")} className="w-12 h-12 object-contain rounded-full"/><span>منصة <span className="text-teal-700">{tx("brand.name")}</span><span className="block text-[10px] font-normal text-slate-500">{tx("brand.sub")}</span></span></button>
          <div className="flex-1 min-w-[160px]"><input value={q} onChange={e=>setQ(e.target.value)} placeholder={tx("header.search")} className="w-full border dark:border-slate-700 dark:bg-slate-800 rounded-full px-4 py-3"/></div>
          <button onClick={toggleTheme} className="px-4 py-3 rounded-full bg-slate-100 dark:bg-slate-800 font-bold">{dark?"☀️ نهاري":"🌙 ليلي"}</button>
          <button onClick={()=>setModal("teacher")} className="px-4 py-3 rounded-full bg-amber-500 text-white font-bold shadow">{tx("header.teacherBtn")}</button>
          <button onClick={()=> data.isDev? setView("admin") : setModal("dev")} className="px-4 py-3 rounded-full bg-slate-900 dark:bg-white dark:text-slate-900 text-white font-bold">{tx("header.devBtn")}</button>
          {user? <>
            <button onClick={()=>setView("profile")} className="px-4 py-3 rounded-full bg-teal-50 dark:bg-slate-800 text-teal-800 dark:text-teal-300 font-bold">👤 {user.name.split(" ")[0]}</button>
            <button onClick={logout} className="px-4 py-3 rounded-full bg-red-50 text-red-600 font-bold">خروج</button>
          </>:<button onClick={()=>setModal("auth")} className="px-5 py-3 rounded-full bg-teal-700 text-white font-bold shadow">{tx("header.loginBtn")}</button>}
        </div>
        <nav className="max-w-7xl mx-auto px-3 pb-2 flex gap-2 overflow-x-auto no-scrollbar text-sm font-bold">
          {[["home",tx("nav.home")],["favorites",tx("nav.favorites")],["history",tx("nav.history")],["profile",tx("nav.profile")]].map(([v,t]:any)=><button key={v} onClick={()=>{ if(!user&&(v!=="home")){setModal("auth");} else setView(v);}} className={`px-4 py-2 rounded-full whitespace-nowrap ${view===v?"bg-teal-700 text-white":"bg-slate-100 dark:bg-slate-800"}`}>{t}</button>)}
          <span className="px-4 py-2 rounded-full bg-emerald-50 text-emerald-700 whitespace-nowrap">🔔 {(data.notifications||[])[0]?.title||"لا إشعارات"}</span>
          {data.isDev && <button onClick={()=>setView("admin")} className="px-4 py-2 rounded-full bg-slate-900 text-white whitespace-nowrap">{tx("header.dashboardBtn")}</button>}
        </nav>
      </header>

      {toast && <div className="fixed bottom-5 left-1/2 -translate-x-1/2 z-[90] bg-slate-900 text-white px-5 py-3 rounded-2xl shadow-2xl font-bold max-w-[92vw] text-center fade-up">{toast}</div>}

      {/* ===== HOME ===== */}
      {view==="home" && <main className="fade-up">
        {visibleSections.map(renderSection)}
      </main>}

      {/* ===== COURSE ===== */}
      {view==="course" && selected && <main className="max-w-7xl mx-auto px-4 py-6 fade-up">
        <button onClick={()=>setView("home")} className="font-bold text-teal-700 mb-4">→ عودة للكورسات</button>
        <div className="grid lg:grid-cols-[1fr_380px] gap-6 items-start">
          <div>
            {lesson?.type==="video" && (lesson.unlocked? <ProtectedPlayer lesson={lesson} userEmail={user?.email} onComplete={async()=>{ if(!user){setModal("auth");return;} await api("/api/platform",{action:"progress",lessonId:lesson.id,courseId:selected.id,completed:true}); showToast("🎉 تم تسجيل إتمام الدرس"); load(); }}/> :
              <div className="aspect-video bg-slate-900 text-white rounded-2xl grid place-items-center p-6 text-center"><div><div className="text-5xl mb-3">🔒</div><h3 className="font-black text-xl">{lesson.title}</h3><p className="text-slate-300 text-sm mt-2">هذا الدرس محمي. أدخل كود الفيديو الخاص به لفتحه ومشاهدته.</p><button onClick={()=> user? setModal("code") : setModal("auth")} className="mt-4 bg-teal-600 px-6 py-4 rounded-2xl font-black">🎟️ إدخال كود الدرس</button></div></div>)}
            {lesson?.type==="pdf" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-2xl p-5"><h3 className="font-black text-xl">📄 {lesson.title}</h3><p className="text-slate-500 mt-1">{lesson.description}</p>{lesson.unlocked? <><iframe src={drivePreview(lesson.url)} className="w-full h-[480px] rounded-xl border mt-4" title="PDF"/>{lesson.allowDownload? <a href={driveDownload(lesson.url)} target="_blank" className="inline-block mt-4 bg-teal-700 text-white px-6 py-4 rounded-xl font-black">⬇️ تنزيل ملف PDF</a>:<p className="mt-3 text-amber-600 font-bold text-sm">🚫 التنزيل غير مسموح لهذا الملف — معاينة فقط</p>}</>:<button onClick={()=>setModal("code")} className="mt-4 bg-teal-700 text-white px-6 py-4 rounded-xl font-black">🔒 فتح الملف بكود</button>}</div>}
            {lesson?.type==="link" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-2xl p-6 text-center"><div className="text-5xl">🔗</div><h3 className="font-black text-xl mt-2">{lesson.title}</h3><p className="text-slate-500 mt-2">{lesson.description}</p><a href={lesson.url} target="_blank" rel="noreferrer" className="inline-block mt-4 bg-teal-700 text-white px-6 py-4 rounded-xl font-black">فتح الرابط في تبويب جديد ↗</a></div>}
            {!lesson && <div className="bg-white dark:bg-slate-900 rounded-2xl p-10 text-center text-slate-500">اختر درساً من القائمة للبدء</div>}
            <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-6 mt-5"><div className="flex gap-2 flex-wrap"><span className="bg-teal-700 text-white px-3 py-1 rounded-full text-xs">{selected.category}</span><span className="bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full text-xs">👨‍🏫 {selected.teacherName}</span><button onClick={()=>setQrCourse(selected)} className="bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full text-xs font-bold">📷 QR الكورس</button><button onClick={()=>{navigator.clipboard.writeText(location.href); showToast("تم نسخ الرابط 🔗");}} className="bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-full text-xs font-bold">↗️ مشاركة</button></div><h1 className="text-2xl font-black mt-3">{selected.title}</h1><p className="text-slate-500 leading-8 mt-2">{selected.description}</p>
            <div className="mt-4"><div className="flex justify-between font-bold text-sm"><span>نسبة إنجاز الكورس</span><span className="text-teal-700">{progressOf(selected.id)}%</span></div><div className="h-3 bg-slate-100 dark:bg-slate-800 rounded-full mt-2 overflow-hidden"><div className="h-full bg-teal-600" style={{width:progressOf(selected.id)+"%"}}/></div></div></div>
          </div>
          <aside className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-4 lg:sticky lg:top-32 max-h-[80vh] overflow-y-auto">
            <h3 className="font-black mb-3">📑 محتوى الكورس ({counts(selected.id).total})</h3>
            {modules.filter((m:any)=>m.courseId===selected.id).map((m:any)=>(
              <div key={m.id} className="mb-4"><h4 className="font-black bg-slate-100 dark:bg-slate-800 rounded-xl px-3 py-2.5 text-sm">{m.title}</h4>
              <div className="mt-2 space-y-2">{lessons.filter((l:any)=>l.courseId===selected.id&&l.moduleId===m.id).map((l:any,idx:number)=>{ const done=(data.progress||[]).find((p:any)=>p.lessonId===l.id)?.isCompleted; return <button key={l.id} onClick={()=>playLesson(l)} className={`w-full text-right border dark:border-slate-800 rounded-xl p-3 flex gap-3 items-center ${lesson?.id===l.id?"border-teal-600 bg-teal-50 dark:bg-slate-800":""}`}>
                {l.thumbnail&&l.type==="video"?<img loading="lazy" src={l.thumbnail} alt="" className="w-16 h-11 object-cover rounded-lg shrink-0"/>:<span className="w-11 h-11 shrink-0 grid place-items-center bg-slate-100 dark:bg-slate-800 rounded-lg text-xl">{l.type==="pdf"?"📄":l.type==="link"?"🔗":"🎬"}</span>}
                <span className="flex-1 min-w-0"><b className="block text-sm truncate">{idx+1}. {l.title}</b><span className="text-xs text-slate-500">{l.duration||""} {l.isFree?"• مجاني 🆓":l.unlocked?"• مفتوح ✅":"• محمي 🔒"} {done?"• مكتمل ✓":""}</span></span><span>{done?"✅":l.unlocked?"▶️":"🔒"}</span></button>; })}</div></div>
            ))}
            {lessons.filter((l:any)=>l.courseId===selected.id&&!l.moduleId).length>0 && <div className="space-y-2">{lessons.filter((l:any)=>l.courseId===selected.id&&!l.moduleId).map((l:any)=><button key={l.id} onClick={()=>playLesson(l)} className="w-full text-right border dark:border-slate-800 rounded-xl p-3 font-bold text-sm">{l.title}</button>)}</div>}
          </aside>
        </div>
      </main>}

      {/* ===== PROFILE / FAVORITES / HISTORY ===== */}
      {view==="profile" && user && <main className="max-w-5xl mx-auto px-4 py-8 fade-up"><div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-6"><div className="flex items-center gap-4 flex-wrap"><span className="w-16 h-16 rounded-full bg-teal-700 text-white grid place-items-center text-2xl font-black">{user.name[0]}</span><div><h1 className="font-black text-xl">{user.name}</h1><p className="text-slate-500 text-sm">{user.email} • {user.role==="developer"?"مطور 👑":user.role==="teacher"?"معلم 👨‍🏫":"طالب 🎓"}</p></div></div>
      <div className="grid grid-cols-3 gap-3 mt-6 text-center"><div className="bg-slate-50 dark:bg-slate-800 rounded-2xl p-4"><b className="text-xl">{(data.progress||[]).filter((p:any)=>p.isCompleted).length}</b><span className="block text-xs">درس مكتمل</span></div><div className="bg-slate-50 dark:bg-slate-800 rounded-2xl p-4"><b className="text-xl">{(data.favorites||[]).length}</b><span className="block text-xs">في المفضلة</span></div><div className="bg-slate-50 dark:bg-slate-800 rounded-2xl p-4"><b className="text-xl">{(data.access||[]).length}</b><span className="block text-xs">درس مفتوح بكود</span></div></div>
      <h3 className="font-black mt-6 mb-3">تقدمي في الكورسات</h3>{courses.map((c:any)=><div key={c.id} className="flex items-center gap-3 border dark:border-slate-800 rounded-2xl p-3 mb-2"><img src={c.image} className="w-14 h-10 rounded-lg object-cover" alt=""/><div className="flex-1"><b className="text-sm">{c.title}</b><div className="h-2 bg-slate-100 dark:bg-slate-800 rounded-full mt-1 overflow-hidden"><div className="h-full bg-teal-600" style={{width:progressOf(c.id)+"%"}}/></div></div><span className="font-black text-teal-700">{progressOf(c.id)}%</span><button onClick={()=>openCourse(c)} className="bg-teal-700 text-white px-4 py-2 rounded-xl font-bold text-sm">متابعة</button></div>)}
      </div></main>}
      {view==="favorites" && <main className="max-w-7xl mx-auto px-4 py-8 fade-up"><h1 className="font-black text-2xl mb-5">❤️ كورساتي المفضلة</h1><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">{courses.filter((c:any)=>isFav(c.id)).map((c:any)=><div key={c.id} className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl overflow-hidden"><img src={c.image} className="h-40 w-full object-cover" alt=""/><div className="p-5"><b>{c.title}</b><button onClick={()=>openCourse(c)} className="block w-full mt-3 bg-teal-700 text-white py-3 rounded-xl font-black">دخول الكورس</button></div></div>)}</div>{!courses.filter((c:any)=>isFav(c.id)).length&&<p className="text-slate-500">لا توجد كورسات مفضلة بعد — اضغط 🤍 على أي كورس</p>}</main>}
      {view==="history" && <main className="max-w-5xl mx-auto px-4 py-8 fade-up"><h1 className="font-black text-2xl mb-5">🕘 سجل المشاهدة وآخر ما شاهدت</h1><div className="space-y-3">{(data.history||[]).map((h:any)=>{ const l=lessons.find((x:any)=>x.id===h.lessonId); const c=courses.find((x:any)=>x.id===h.courseId); if(!l) return null; return <div key={h.id} className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-2xl p-4 flex items-center gap-3 flex-wrap"><span className="text-2xl">{l.type==="pdf"?"📄":"🎬"}</span><div className="flex-1"><b>{l.title}</b><span className="block text-xs text-slate-500">{c?.title} • {fmtDate(h.watchedAt)}</span></div><button onClick={()=>{ if(c){openCourse(c); setTimeout(()=>playLesson(l),80);} }} className="bg-teal-700 text-white px-5 py-3 rounded-xl font-bold">استكمال المشاهدة</button></div>;})}</div>{!(data.history||[]).length&&<p className="text-slate-500">لا يوجد سجل بعد</p>}</main>}

      {/* ===== ADMIN ===== */}
      {view==="admin" && (data.isDev? <main className="max-w-7xl mx-auto px-3 py-6 fade-up">
        <div className="flex gap-4 items-start flex-col lg:flex-row">
          <aside className="lg:w-64 w-full bg-slate-900 text-white rounded-3xl p-4 lg:sticky lg:top-28 shrink-0">
            <h2 className="font-black text-lg">⚙️ لوحة المطور</h2><p className="text-xs text-slate-400 mt-1">{user?.email||"adhm99486@gmail.com"} • مطور 👑</p>
            <div className="flex lg:flex-col gap-2 mt-4 overflow-x-auto no-scrollbar">{[["dashboard","📊 الإحصائيات"],["courses","📚 الكورسات"],["create","＋ إنشاء كورس جديد"],["content","🎬 الفيديوهات و PDF والروابط"],["codes","🎟️ أكواد الفيديوهات"],["users","👥 المستخدمون والمطورون"],["teachers","👨‍🏫 طلبات المعلمين"],["search","🔍 البحث الشامل"],["logs","🧾 سجل العمليات"],["site","🎨 تخصيص الواجهة"],["settings","🔐 الإعدادات والنسخ"]].map(([t,l]:any)=><button key={t} onClick={()=>setAdminTab(t)} className={`text-right px-4 py-3 rounded-xl font-bold whitespace-nowrap ${adminTab===t?"bg-teal-600":"bg-white/10"}`}>{l}</button>)}</div>
            <button onClick={logout} className="mt-4 w-full bg-red-600 py-3 rounded-xl font-bold">تسجيل خروج المطور</button>
          </aside>

          <section className="flex-1 min-w-0 w-full">
            {!admin? <p className="bg-white dark:bg-slate-900 rounded-3xl p-8">جاري تحميل بيانات لوحة التحكم...</p> : <>
            {adminTab==="dashboard" && <div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">{[[admin.stats.users,"👥 مستخدم"],[admin.stats.courses,"📚 كورس"],[admin.stats.videos,"🎬 فيديو"],[admin.stats.pdfs,"📄 PDF"],[admin.stats.links,"🔗 رابط"],[admin.stats.views,"👁️ مشاهدة"],[admin.stats.codesActive,"🎟️ كود فعال"],[admin.stats.codesExpired,"⌛ كود منتهي"]].map(([n,l]:any)=><div key={l} className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5 text-center"><b className="text-3xl text-teal-700">{n}</b><span className="block text-sm mt-1">{l}</span></div>)}</div>
              <div className="grid md:grid-cols-2 gap-4 mt-4">
                <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black mb-3">🔥 أكثر الفيديوهات مشاهدة</h3>{admin.topVideos.map((v:any)=><div key={v.id} className="flex justify-between border-b dark:border-slate-800 py-2 text-sm"><span>{v.title}</span><b>👁️ {v.views||0}</b></div>)}</div>
                <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black mb-3">👥 آخر المستخدمين ونسبة تقدمهم</h3>{admin.users.slice(0,6).map((u:any)=>{ const done=admin.progress.filter((p:any)=>p.userId===u.id&&p.isCompleted).length; return <div key={u.id} className="flex justify-between border-b dark:border-slate-800 py-2 text-sm"><span>{u.name} <span className="text-slate-400">({u.role})</span></span><b>{done} درس ✓</b></div>; })}</div>
              </div>
            </div>}

            {adminTab==="courses" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><div className="flex justify-between flex-wrap gap-2"><h3 className="font-black text-lg">إدارة الكورسات (اسحب لإعادة الترتيب)</h3><button onClick={()=>setAdminTab("create")} className="bg-teal-700 text-white px-5 py-3 rounded-xl font-black">＋ إنشاء كورس جديد</button></div>
              <div className="space-y-3 mt-4">{admin.courses.map((c:any)=> <div key={c.id} draggable onDragStart={()=>dragId.current=c.id} onDragOver={e=>e.preventDefault()} onDrop={async()=>{ const ids=admin.courses.map((x:any)=>x.id); const from=ids.indexOf(dragId.current); const to=ids.indexOf(c.id); ids.splice(to,0,ids.splice(from,1)[0]); await adminAct({action:"reorder-courses",ids},"تم إعادة ترتيب الكورسات ↕️"); }} className="border dark:border-slate-800 rounded-2xl p-3 cursor-grab">
                <div className="grid md:grid-cols-[1fr_auto] gap-3"><div className="grid md:grid-cols-2 gap-2"><input defaultValue={c.title} id={`ct-${c.id}`} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5 font-bold" placeholder="اسم الكورس"/><input defaultValue={c.teacherName} id={`cte-${c.id}`} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5" placeholder="اسم المعلم"/><input defaultValue={c.image} id={`ci-${c.id}`} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5 md:col-span-2" placeholder="رابط صورة الكورس"/><textarea defaultValue={c.description} id={`cd-${c.id}`} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5 md:col-span-2" placeholder="وصف الكورس"/></div>
                <div className="flex md:flex-col gap-2"><button onClick={async()=>{ await adminAct({action:"update-course",id:c.id,title:(document.getElementById(`ct-${c.id}`) as any).value,teacherName:(document.getElementById(`cte-${c.id}`) as any).value,image:(document.getElementById(`ci-${c.id}`) as any).value,description:(document.getElementById(`cd-${c.id}`) as any).value,category:c.category,level:c.level,isPublished:c.isPublished,sortOrder:c.sortOrder},"تم حفظ الكورس ✅"); }} className="bg-teal-700 text-white px-4 py-2.5 rounded-xl font-bold">حفظ</button>
                <button onClick={async()=>{ await adminAct({action:"update-course",...c,isPublished:!c.isPublished},c.isPublished?"تم إخفاء الكورس":"تم نشر الكورس 🎉"); }} className="bg-amber-500 text-white px-4 py-2.5 rounded-xl font-bold">{c.isPublished?"إخفاء":"نشر"}</button>
                <button onClick={async()=>{ if(confirm("حذف الكورس نهائياً؟")) await adminAct({action:"delete-course",id:c.id},"تم حذف الكورس"); }} className="bg-red-600 text-white px-4 py-2.5 rounded-xl font-bold">حذف</button></div></div>
                <p className="text-xs text-slate-500 mt-2">🎬 {admin.lessons.filter((l:any)=>l.courseId===c.id&&l.type==="video").length} فيديو • 📄 {admin.lessons.filter((l:any)=>l.courseId===c.id&&l.type==="pdf").length} PDF • 🔗 {admin.lessons.filter((l:any)=>l.courseId===c.id&&l.type==="link").length} رابط • {c.isPublished?"منشور ✅":"مخفي 🚫"}</p></div>)}
              </div>
              <div className="mt-6 border-t dark:border-slate-800 pt-4"><h4 className="font-black">إنشاء وحدة / فصل داخل كورس</h4><div className="flex gap-2 flex-wrap mt-2"><select id="module-course" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3">{admin.courses.map((c:any)=><option key={c.id} value={c.id}>{c.title}</option>)}</select><input value={moduleTitle} onChange={e=>setModuleTitle(e.target.value)} placeholder="اسم الوحدة الجديدة" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3 flex-1"/><button onClick={async()=>{ await adminAct({action:"create-module",courseId:(document.getElementById("module-course") as any).value,title:moduleTitle},"تم إنشاء الوحدة ✅"); setModuleTitle(""); }} className="bg-slate-900 dark:bg-white dark:text-black text-white px-5 rounded-xl font-bold">إنشاء وحدة</button></div></div>
            </div>}

            {adminTab==="create" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-xl">＋ إنشاء كورس جديد (معالج كامل)</h3><p className="text-sm text-slate-500 mt-1">الخطوات: الاسم والوصف والصورة ← الوحدات ← الفيديوهات والـ PDF والروابط ← تُنشأ الأكواد تلقائياً للفيديوهات المحمية ← حفظ ونشر</p>
              <div className="grid md:grid-cols-2 gap-3 mt-4">{[["title","اسم الكورس *"],["teacherName","اسم المعلم"],["image","رابط صورة الكورس"],["category","التصنيف (برمجة / رياضيات / لغات)"]].map(([k,ph]:any)=><input key={k} value={wizard[k]} onChange={e=>setWizard({...wizard,[k]:e.target.value})} placeholder={ph} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3"/>)}<textarea value={wizard.description} onChange={e=>setWizard({...wizard,description:e.target.value})} placeholder="وصف الكورس" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3 md:col-span-2"/></div>
              {wizard.modules.map((m:any,mi:number)=><div key={mi} className="border dark:border-slate-800 rounded-2xl p-4 mt-4"><input value={m.title} onChange={e=>{ const w={...wizard}; w.modules[mi].title=e.target.value; setWizard(w); }} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5 font-bold w-full" placeholder="اسم الوحدة"/>
                {m.lessons.map((l:any,li:number)=><div key={li} className="grid md:grid-cols-4 gap-2 mt-2"><select value={l.type} onChange={e=>{const w={...wizard}; w.modules[mi].lessons[li].type=e.target.value; setWizard(w);}} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-2 py-2.5"><option value="video">🎬 فيديو يوتيوب</option><option value="pdf">📄 PDF درايف</option><option value="link">🔗 رابط خارجي</option></select><input value={l.title} onChange={e=>{const w={...wizard}; w.modules[mi].lessons[li].title=e.target.value; setWizard(w);}} placeholder="عنوان الدرس" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5"/><input value={l.youtubeId||l.url||""} onChange={e=>{const w={...wizard}; if(w.modules[mi].lessons[li].type==="video") w.modules[mi].lessons[li].youtubeId=e.target.value; else w.modules[mi].lessons[li].url=e.target.value; setWizard(w);}} placeholder="رابط يوتيوب / درايف / خارجي" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-2.5"/><label className="flex items-center gap-1 text-sm font-bold"><input type="checkbox" checked={l.isFree} onChange={e=>{const w={...wizard}; w.modules[mi].lessons[li].isFree=e.target.checked; w.modules[mi].lessons[li].isProtected=!e.target.checked; setWizard(w);}}/> مجاني للمعاينة</label></div>)}
                <button onClick={()=>{ const w={...wizard}; w.modules[mi].lessons.push({type:"video",title:"",youtubeId:"",url:"",isFree:false,isProtected:true}); setWizard(w); }} className="mt-2 bg-slate-100 dark:bg-slate-800 px-4 py-2 rounded-xl font-bold text-sm">＋ إضافة درس للوحدة</button></div>)}
              <div className="flex gap-2 mt-4 flex-wrap"><button onClick={()=>setWizard({...wizard,modules:[...wizard.modules,{title:`الوحدة ${wizard.modules.length+1}`,lessons:[{type:"video",title:"",youtubeId:"",isFree:false,isProtected:true}]}]})} className="bg-slate-900 dark:bg-white dark:text-black text-white px-5 py-3 rounded-xl font-bold">＋ إضافة وحدة</button>
              <button onClick={async()=>{ if(!wizard.title) return showToast("اكتب اسم الكورس"); await adminAct({action:"create-course",...wizard},"🎉 تم إنشاء ونشر الكورس مع أكواده تلقائياً"); setAdminTab("courses"); }} className="bg-teal-700 text-white px-7 py-3 rounded-xl font-black">💾 حفظ ونشر الكورس</button></div>
            </div>}

            {adminTab==="content" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-lg">إضافة / تعديل محتوى (فيديو يوتيوب • PDF درايف • رابط)</h3>
              <div className="grid md:grid-cols-3 gap-2 mt-4">
                <select value={lessonForm.type} onChange={e=>setLessonForm({...lessonForm,type:e.target.value})} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"><option value="video">🎬 فيديو يوتيوب</option><option value="pdf">📄 ملف PDF (درايف)</option><option value="link">🔗 رابط خارجي</option></select>
                <select value={lessonForm.courseId} onChange={e=>setLessonForm({...lessonForm,courseId:e.target.value})} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"><option value="">اختر الكورس *</option>{admin.courses.map((c:any)=><option key={c.id} value={c.id}>{c.title}</option>)}</select>
                <select value={lessonForm.moduleId} onChange={e=>setLessonForm({...lessonForm,moduleId:e.target.value})} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"><option value="">بدون وحدة</option>{(data.modules||[]).filter((m:any)=>!lessonForm.courseId||m.courseId===Number(lessonForm.courseId)).map((m:any)=><option key={m.id} value={m.id}>{m.title}</option>)}</select>
                <input value={lessonForm.title} onChange={e=>setLessonForm({...lessonForm,title:e.target.value})} placeholder="عنوان الدرس / الملف / الرابط *" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/>
                <input value={lessonForm.youtubeId} onChange={e=>setLessonForm({...lessonForm,youtubeId:e.target.value})} placeholder="رابط أو ID فيديو يوتيوب" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/>
                <input value={lessonForm.url} onChange={e=>setLessonForm({...lessonForm,url:e.target.value})} placeholder="رابط PDF درايف أو رابط خارجي" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/>
                <input value={lessonForm.duration} onChange={e=>setLessonForm({...lessonForm,duration:e.target.value})} placeholder="المدة (مثال 24:10)" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/>
                <input value={lessonForm.thumbnail} onChange={e=>setLessonForm({...lessonForm,thumbnail:e.target.value})} placeholder="رابط صورة مصغرة (اختياري)" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/>
                <input value={lessonForm.description} onChange={e=>setLessonForm({...lessonForm,description:e.target.value})} placeholder="وصف الدرس" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/>
              </div>
              <div className="flex gap-4 flex-wrap mt-3 font-bold text-sm"><label className="flex gap-1 items-center"><input type="checkbox" checked={lessonForm.isFree} onChange={e=>setLessonForm({...lessonForm,isFree:e.target.checked})}/> مجاني للمعاينة 🆓</label><label className="flex gap-1 items-center"><input type="checkbox" checked={lessonForm.isProtected} onChange={e=>setLessonForm({...lessonForm,isProtected:e.target.checked})}/> حماية بكود 🔒</label><label className="flex gap-1 items-center"><input type="checkbox" checked={lessonForm.allowDownload} onChange={e=>setLessonForm({...lessonForm,allowDownload:e.target.checked})}/> السماح بالتنزيل ⬇️</label></div>
              <button onClick={async()=>{ if(!lessonForm.title||!lessonForm.courseId) return showToast("اختر الكورس واكتب العنوان"); await adminAct({action:"save-lesson",id:editLessonId,...lessonForm}, editLessonId?"تم تعديل المحتوى ✅":"تمت إضافة المحتوى وإنشاء كوده تلقائياً 🎟️"); setLessonForm({type:"video",title:"",description:"",youtubeId:"",url:"",duration:"",isFree:false,isProtected:true,allowDownload:false,courseId:"",moduleId:""}); setEditLessonId(null); }} className="mt-4 bg-teal-700 text-white px-7 py-3.5 rounded-xl font-black">{editLessonId?"حفظ التعديل":"＋ إضافة المحتوى"}</button>
              <h4 className="font-black mt-8 mb-3">كل المحتوى — اسحب ↕️ لإعادة الترتيب</h4>
              <div className="space-y-2 max-h-[520px] overflow-y-auto">{admin.lessons.map((l:any)=><div key={l.id} draggable onDragStart={()=>dragId.current=l.id} onDragOver={e=>e.preventDefault()} onDrop={async()=>{ const same=admin.lessons.filter((x:any)=>x.courseId===l.courseId); const ids=same.map((x:any)=>x.id); const from=ids.indexOf(dragId.current); const to=ids.indexOf(l.id); if(from<0) return; ids.splice(to,0,ids.splice(from,1)[0]); await adminAct({action:"reorder-lessons",ids},"تم إعادة الترتيب ↕️"); }} className="flex items-center gap-2 border dark:border-slate-800 rounded-xl p-3 cursor-grab flex-wrap"><span>{l.type==="video"?"🎬":l.type==="pdf"?"📄":"🔗"}</span><span className="flex-1 min-w-[160px]"><b className="text-sm block">{l.title}</b><span className="text-xs text-slate-500">{admin.courses.find((c:any)=>c.id===l.courseId)?.title} • 👁️ {l.views||0} • {l.isFree?"مجاني":l.isProtected?"محمي بكود":"مفتوح"} {l.type!=="link"?(l.allowDownload?"• تنزيل مسموح":"• تنزيل ممنوع"):""}</span></span>
                <button onClick={()=>{ setEditLessonId(l.id); setLessonForm({type:l.type,title:l.title,description:l.description||"",youtubeId:l.youtubeId||"",url:l.url||"",duration:l.duration||"",thumbnail:l.thumbnail||"",isFree:l.isFree,isProtected:l.isProtected,allowDownload:l.allowDownload,courseId:l.courseId,moduleId:l.moduleId||""}); window.scrollTo({top:0,behavior:"smooth"}); }} className="bg-slate-100 dark:bg-slate-800 px-4 py-2 rounded-lg font-bold text-sm">تعديل</button>
                <button onClick={async()=>{ await adminAct({action:"save-lesson",id:l.id,...l,allowDownload:!l.allowDownload},l.allowDownload?"تم منع التنزيل":"تم السماح بالتنزيل ⬇️"); }} className="bg-amber-100 text-amber-800 px-3 py-2 rounded-lg font-bold text-sm">التنزيل: {l.allowDownload?"مسموح":"ممنوع"}</button>
                <button onClick={async()=>{ if(confirm("حذف هذا المحتوى؟")) await adminAct({action:"delete-lesson",id:l.id},"تم الحذف"); }} className="bg-red-600 text-white px-4 py-2 rounded-lg font-bold text-sm">حذف</button></div>)}</div>
            </div>}

            {adminTab==="codes" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-lg">🎟️ نظام أكواد الفيديوهات المحمية</h3>
              <div className="grid md:grid-cols-4 gap-2 mt-4"><select value={codeGen.lessonId} onChange={e=>setCodeGen({...codeGen,lessonId:e.target.value})} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"><option value="">اختر الفيديو *</option>{admin.lessons.filter((l:any)=>l.type==="video").map((l:any)=><option key={l.id} value={l.id}>{l.title}</option>)}</select><input type="number" value={codeGen.count} onChange={e=>setCodeGen({...codeGen,count:e.target.value})} placeholder="عدد الأكواد" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><input type="number" value={codeGen.maxUses} onChange={e=>setCodeGen({...codeGen,maxUses:e.target.value})} placeholder="مرات الاستخدام (1 = مرة واحدة)" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><input type="datetime-local" value={codeGen.expiresAt} onChange={e=>setCodeGen({...codeGen,expiresAt:e.target.value})} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/></div>
              <input value={codeGen.customCode} onChange={e=>setCodeGen({...codeGen,customCode:e.target.value})} placeholder="كود مخصص (اختياري — عند إنشاء كود واحد فقط)" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3 w-full mt-2"/>
              <div className="flex gap-2 flex-wrap mt-3"><button onClick={async()=>{ if(!codeGen.lessonId) return showToast("اختر الفيديو أولاً"); const r=await adminAct({action:"generate-codes",...codeGen},"🎟️ تم إنشاء الأكواد بنجاح"); if(r?.created) showToast(`تم إنشاء ${r.created.length} كود`); }} className="bg-teal-700 text-white px-6 py-3.5 rounded-xl font-black">⚡ إنشاء مجموعة أكواد دفعة واحدة</button>
              <button onClick={()=>{ const txt=admin.codes.map((c:any)=>`${c.code},درس ${c.lessonId},${codeStatus(c).t},استخدم ${c.usedCount}/${c.maxUses}`).join("\n"); downloadText("codes.csv","code,lesson,status,uses\n"+txt,"text/csv"); }} className="bg-slate-900 dark:bg-white dark:text-black text-white px-5 py-3.5 rounded-xl font-bold">⬇️ تصدير CSV</button></div>
              <div className="flex gap-2 mt-3 flex-wrap"><input value={importCsv} onChange={e=>setImportCsv(e.target.value)} placeholder="الصق أكواد مفصولة بفواصل أو أسطر لاستيرادها CSV" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3 flex-1"/><button onClick={async()=>{ if(!codeGen.lessonId) return showToast("اختر الفيديو أولاً"); await adminAct({action:"import-codes",lessonId:codeGen.lessonId,csv:importCsv,maxUses:codeGen.maxUses},"تم استيراد الأكواد ✅"); setImportCsv(""); }} className="bg-amber-500 text-white px-5 rounded-xl font-bold">استيراد أكواد</button></div>
              <div className="space-y-2 mt-5 max-h-[520px] overflow-y-auto">{admin.codes.map((c:any)=>{ const st=codeStatus(c); const les=admin.lessons.find((l:any)=>l.id===c.lessonId); return <div key={c.id} className="flex items-center gap-2 border dark:border-slate-800 rounded-xl p-3 flex-wrap"><code className="font-black bg-slate-100 dark:bg-slate-800 px-3 py-2 rounded-lg" dir="ltr">{c.code}</code><span className={`px-2 py-1 rounded-full text-xs font-bold ${st.cls}`}>{st.t}</span><span className="text-xs text-slate-500 flex-1">{les?.title||"درس محذوف"} • استخدم {c.usedCount}/{c.maxUses} • ينتهي: {fmtDate(c.expiresAt)}</span>
                <button onClick={()=>{navigator.clipboard.writeText(c.code); showToast("📋 تم نسخ الكود");}} className="bg-teal-50 text-teal-700 px-3 py-2 rounded-lg font-bold text-sm">نسخ</button>
                <button onClick={async()=>await adminAct({action:"update-code",id:c.id,isActive:!c.isActive},c.isActive?"تم إيقاف الكود":"تم تفعيل الكود")} className="bg-slate-100 dark:bg-slate-800 px-3 py-2 rounded-lg font-bold text-sm">{c.isActive?"إيقاف":"تفعيل"}</button>
                <button onClick={async()=>{ const r=await adminAct({action:"regenerate-code",id:c.id},"تم إعادة إنشاء الكود 🔄"); }} className="bg-amber-100 text-amber-800 px-3 py-2 rounded-lg font-bold text-sm">إعادة إنشاء</button>
                <button onClick={async()=>{ const nc=prompt("تعديل الكود يدوياً:",c.code); if(nc) await adminAct({action:"update-code",id:c.id,code:nc},"تم تعديل الكود"); }} className="bg-slate-100 dark:bg-slate-800 px-3 py-2 rounded-lg font-bold text-sm">تعديل</button>
                <button onClick={async()=>await adminAct({action:"delete-code",id:c.id},"تم حذف الكود")} className="bg-red-600 text-white px-3 py-2 rounded-lg font-bold text-sm">حذف</button></div>; })}</div>
            </div>}

            {adminTab==="users" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-lg">👥 المستخدمون — إضافة مطور / معلم / طالب</h3><p className="text-xs text-slate-500 mt-1">حساب المطور الرئيسي الوحيد المعتمد: adhm99486@gmail.com — ويمكن إضافة مطورين ومعلمين آخرين من هنا</p>
              <div className="grid md:grid-cols-4 gap-2 mt-4"><input value={newUser.name} onChange={e=>setNewUser({...newUser,name:e.target.value})} placeholder="الاسم" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><input value={newUser.email} onChange={e=>setNewUser({...newUser,email:e.target.value})} placeholder="البريد الإلكتروني" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><input value={newUser.password} onChange={e=>setNewUser({...newUser,password:e.target.value})} placeholder="كلمة المرور" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><select value={newUser.role} onChange={e=>setNewUser({...newUser,role:e.target.value})} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"><option value="developer">مطور 👑</option><option value="teacher">معلم 👨‍🏫</option><option value="student">طالب 🎓</option></select></div>
              <button onClick={async()=>{ await adminAct({action:"add-user",...newUser},"تمت الإضافة بنجاح ✅"); setNewUser({name:"",email:"",password:"",role:"teacher"}); }} className="mt-3 bg-teal-700 text-white px-6 py-3.5 rounded-xl font-black">＋ إضافة {newUser.role==="developer"?"مطور":newUser.role==="teacher"?"معلم":"طالب"}</button>
              <div className="space-y-2 mt-5">{admin.users.map((u:any)=><div key={u.id} className="flex items-center gap-2 border dark:border-slate-800 rounded-xl p-3 flex-wrap"><span className="w-10 h-10 rounded-full bg-teal-700 text-white grid place-items-center font-black">{u.name?.[0]}</span><span className="flex-1"><b className="text-sm block">{u.name}</b><span className="text-xs text-slate-500">{u.email} • منذ {fmtDate(u.createdAt)}</span></span><select defaultValue={u.role} onChange={async e=>await adminAct({action:"update-role",id:u.id,role:e.target.value},"تم تغيير الصلاحية")} className="border dark:border-slate-700 dark:bg-slate-800 rounded-lg px-2 py-2 text-sm"><option value="student">طالب</option><option value="teacher">معلم</option><option value="developer">مطور</option></select><span className="text-xs bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-full">{admin.progress.filter((p:any)=>p.userId===u.id&&p.isCompleted).length} درس مكتمل</span>{u.email!=="adhm99486@gmail.com"&&<button onClick={async()=>{if(confirm("حذف المستخدم؟")) await adminAct({action:"delete-user",id:u.id},"تم الحذف");}} className="bg-red-600 text-white px-3 py-2 rounded-lg text-sm font-bold">حذف</button>}</div>)}</div>
            </div>}

            {adminTab==="teachers" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-lg">👨‍🏫 طلبات انضمام المعلمين (من زر «انضم كمعلم» بالخارج)</h3><div className="space-y-2 mt-4">{admin.teacherRequests.map((r:any)=><div key={r.id} className="border dark:border-slate-800 rounded-xl p-4 flex gap-2 flex-wrap items-center"><span className="flex-1"><b>{r.name}</b><span className="block text-xs text-slate-500">{r.email} • {r.subject} • {r.message} • {r.status}</span></span><button onClick={async()=>{ const res=await adminAct({action:"teacher-request-status",id:r.id,status:"approved",email:r.email,name:r.name},"تم قبول المعلم ✅"); if(res?.tempPassword) showToast(`كلمة مرور المعلم المؤقتة: ${res.tempPassword}`); }} className="bg-teal-700 text-white px-4 py-2.5 rounded-xl font-bold text-sm">قبول وإنشاء حساب معلم</button><button onClick={async()=>await adminAct({action:"teacher-request-status",id:r.id,status:"rejected"},"تم الرفض")} className="bg-red-600 text-white px-4 py-2.5 rounded-xl font-bold text-sm">رفض</button></div>)}{!admin.teacherRequests.length&&<p className="text-slate-500">لا توجد طلبات بعد</p>}</div></div>}

            {adminTab==="search" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-lg">🔍 بحث شامل: كورس • فيديو • PDF • رابط • مستخدم • كود</h3><input value={searchAdmin} onChange={e=>setSearchAdmin(e.target.value)} placeholder="اكتب كلمة البحث..." className="w-full border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3.5 mt-4"/>{admin.search&&<div className="mt-4 space-y-3 text-sm"><p>📚 كورسات: {admin.search.courses.map((c:any)=>c.title).join("، ")||"لا نتائج"}</p><p>🎬 محتوى: {admin.search.lessons.map((l:any)=>`${l.type==="pdf"?"📄":l.type==="link"?"🔗":"🎬"} ${l.title}`).join("، ")||"لا نتائج"}</p><p>👥 مستخدمون: {admin.search.users.map((u:any)=>`${u.name} (${u.email})`).join("، ")||"لا نتائج"}</p><p>🎟️ أكواد: {admin.search.codes.map((c:any)=>c.code).join("، ")||"لا نتائج"}</p></div>}</div>}

            {adminTab==="logs" && <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black text-lg">🧾 سجل العمليات المهمة (Audit Log)</h3><div className="space-y-2 mt-4 max-h-[560px] overflow-y-auto">{admin.logs.map((l:any)=><div key={l.id} className="border-b dark:border-slate-800 py-2 text-sm"><b>{l.action}</b><span className="text-slate-500"> — {l.actor} • {l.details} • {fmtDate(l.createdAt)}</span></div>)}</div></div>}

            {adminTab==="site" && <SiteEditor site={site} save={saveSite} upload={uploadAsset} notify={showToast}/>}
            {adminTab==="settings" && <div className="space-y-4"><div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black">🔐 تغيير كلمة مرور المطور</h3><div className="grid md:grid-cols-2 gap-2 mt-3"><input type="password" value={devChange.current} onChange={e=>setDevChange({...devChange,current:e.target.value})} placeholder="كلمة المرور الحالية" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><input type="password" value={devChange.next} onChange={e=>setDevChange({...devChange,next:e.target.value})} placeholder="الجديدة" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/></div><button onClick={async()=>{ await adminAct({action:"change-dev-password",...devChange},"تم تغيير كلمة مرور المطور 🔐"); setDevChange({current:"",next:""}); }} className="mt-3 bg-slate-900 dark:bg-white dark:text-black text-white px-6 py-3 rounded-xl font-bold">حفظ كلمة المرور</button></div>
            <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black">🔔 إرسال إشعار داخل الموقع</h3><div className="grid gap-2 mt-3"><input value={notifyForm.title} onChange={e=>setNotifyForm({...notifyForm,title:e.target.value})} placeholder="عنوان الإشعار" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><input value={notifyForm.body} onChange={e=>setNotifyForm({...notifyForm,body:e.target.value})} placeholder="نص الإشعار" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-3 py-3"/><button onClick={async()=>await adminAct({action:"notify",...notifyForm},"تم إرسال الإشعار 🔔")} className="bg-teal-700 text-white py-3 rounded-xl font-bold">إرسال</button></div></div>
            <div className="bg-white dark:bg-slate-900 border dark:border-slate-800 rounded-3xl p-5"><h3 className="font-black">💾 النسخ الاحتياطي واستعادته</h3><div className="flex gap-2 flex-wrap mt-3"><button onClick={async()=>{ const r=await api("/api/admin",{action:"backup"}); setBackupData(r.backup); downloadText("mohamed-helal-backup.json",JSON.stringify(r.backup,null,2),"application/json"); showToast("تم تنزيل النسخة الاحتياطية 💾"); }} className="bg-teal-700 text-white px-5 py-3 rounded-xl font-bold">تنزيل نسخة احتياطية JSON</button><button onClick={async()=>{ if(!backupData) return showToast("نزّل نسخة أولاً في هذه الجلسة"); await adminAct({action:"restore",backup:backupData},"تم تسجيل الاستعادة"); }} className="bg-amber-500 text-white px-5 py-3 rounded-xl font-bold">استعادة النسخة</button></div><p className="text-xs text-slate-500 mt-2">حدود الخطة المجانية: الفيديوهات على YouTube والـ PDF على Drive (15GB مجاناً)، والنشر مجاناً على Vercel + قاعدة Neon/Supabase المجانية — بدون بطاقة بنكية.</p></div></div>}
            </>}
          </section>
        </div>
      </main> : <main className="max-w-md mx-auto px-4 py-16 text-center"><p className="text-5xl mb-3">🔒</p><h1 className="font-black text-xl">لوحة المطور محمية</h1><p className="text-slate-500 mt-2">هذه المنطقة للمطور فقط (adhm99486@gmail.com)</p><button onClick={()=>setModal("dev")} className="mt-4 bg-slate-900 text-white px-6 py-4 rounded-2xl font-black">دخول المطور</button></main>)}

      <footer className="bg-slate-900 text-white mt-4"><div className="max-w-7xl mx-auto px-4 py-8 flex flex-wrap gap-4 items-center justify-between"><div><b className="text-lg">{tx("footer.title")}</b><p className="text-slate-400 text-sm mt-1">{tx("footer.desc")}</p></div><div className="flex gap-2"><button onClick={()=>setModal("teacher")} className="bg-amber-500 px-4 py-3 rounded-xl font-bold">{tx("footer.teacherBtn")}</button><button onClick={()=>setModal("dev")} className="bg-white/10 px-4 py-3 rounded-xl font-bold">{tx("footer.devBtn")}</button></div></div></footer>

      {/* ===== MODALS ===== */}
      {modal==="auth" && <div className="fixed inset-0 z-[80] bg-black/60 grid place-items-center p-3" onClick={()=>setModal("")}><div className="bg-white dark:bg-slate-900 rounded-3xl p-6 w-full max-w-md fade-up" onClick={e=>e.stopPropagation()}><h3 className="font-black text-xl text-center">🎓 تسجيل الدخول / إنشاء حساب</h3><div className="grid gap-2 mt-4"><input value={authForm.name} onChange={e=>setAuthForm({...authForm,name:e.target.value})} placeholder="اسم المستخدم (للحساب الجديد)" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3.5"/><input value={authForm.email} onChange={e=>setAuthForm({...authForm,email:e.target.value})} placeholder="البريد الإلكتروني" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3.5"/><input type="password" value={authForm.password} onChange={e=>setAuthForm({...authForm,password:e.target.value})} placeholder="كلمة المرور" className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3.5"/></div>{forgotTemp&&<p className="bg-amber-50 text-amber-800 rounded-xl p-3 mt-3 text-sm font-bold">كلمة المرور المؤقتة: <span dir="ltr">{forgotTemp}</span> — سجل بها ثم غيّرها من ملفك</p>}<div className="grid grid-cols-2 gap-2 mt-4"><button onClick={()=>doAuth("login")} className="bg-teal-700 text-white py-4 rounded-xl font-black">تسجيل الدخول</button><button onClick={()=>doAuth("register")} className="bg-slate-900 dark:bg-white dark:text-black text-white py-4 rounded-xl font-black">إنشاء حساب</button></div><button onClick={()=>doAuth("forgot")} className="w-full mt-2 text-teal-700 font-bold py-2">نسيت كلمة المرور؟ تواصل مع المطور</button><button onClick={()=>setModal("")} className="w-full text-slate-400 py-1">إغلاق ✕</button></div></div>}

      {modal==="dev" && <div className="fixed inset-0 z-[80] bg-black/70 grid place-items-center p-3" onClick={()=>setModal("")}><div className="bg-slate-900 text-white rounded-3xl p-6 w-full max-w-md fade-up border border-white/10" onClick={e=>e.stopPropagation()}><h3 className="font-black text-xl text-center">{"</>"} دخول المطور</h3><p className="text-slate-400 text-sm text-center mt-1">هذه المنطقة محمية ومخصصة للمطور فقط<br/>adhm99486@gmail.com</p><input type="password" value={devPw} onChange={e=>setDevPw(e.target.value)} onKeyDown={e=>e.key==="Enter"&&doDevLogin()} placeholder="كلمة مرور المطور" className="w-full bg-white/10 border border-white/15 rounded-xl px-4 py-4 mt-4"/><button onClick={doDevLogin} className="w-full bg-teal-600 py-4 rounded-xl font-black mt-3">🔓 دخول لوحة التحكم</button><p className="text-xs text-slate-500 text-center mt-3">حماية من التخمين: قفل 15 دقيقة بعد 5 محاولات.</p><button onClick={()=>setModal("")} className="w-full text-slate-400 py-2">إغلاق ✕</button></div></div>}

      {modal==="teacher" && <div className="fixed inset-0 z-[80] bg-black/60 grid place-items-center p-3" onClick={()=>setModal("")}><div className="bg-white dark:bg-slate-900 rounded-3xl p-6 w-full max-w-md fade-up" onClick={e=>e.stopPropagation()}><h3 className="font-black text-xl text-center">{tx("teacher.title")}</h3><p className="text-sm text-slate-500 text-center mt-1">{tx("teacher.desc")}</p><div className="grid gap-2 mt-4">{[["name","الاسم الكامل *"],["email","البريد الإلكتروني *"],["subject","المادة / التخصص"],["message","نبذة عنك وخبرتك"]].map(([k,ph]:any)=><input key={k} value={(teacherForm as any)[k]} onChange={e=>setTeacherForm({...teacherForm,[k]:e.target.value})} placeholder={ph} className="border dark:border-slate-700 dark:bg-slate-800 rounded-xl px-4 py-3.5"/>)}</div><button onClick={async()=>{ try{ await api("/api/auth",{action:"teacher-request",...teacherForm}); showToast("✅ تم إرسال طلبك للمطور بنجاح"); setModal(""); }catch(e:any){ showToast("❌ "+e.message); } }} className="w-full bg-amber-500 text-white py-4 rounded-xl font-black mt-4">{tx("teacher.submit")}</button><button onClick={()=>setModal("")} className="w-full text-slate-400 py-2">إغلاق ✕</button></div></div>}

      {modal==="code" && lesson && <div className="fixed inset-0 z-[80] bg-black/60 grid place-items-center p-3" onClick={()=>setModal("")}><div className="bg-white dark:bg-slate-900 rounded-3xl p-6 w-full max-w-md fade-up text-center" onClick={e=>e.stopPropagation()}><div className="text-5xl">🎟️</div><h3 className="font-black text-xl mt-2">إدخال كود الدرس</h3><p className="text-sm text-slate-500 mt-1">{lesson.title}<br/>الكود مرتبط بهذا الدرس فقط ويُتحقق منه على الخادم قبل التشغيل</p><input value={codeInput} onChange={e=>setCodeInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&redeem()} placeholder="VID-XXXX-XXXX-XXXX" dir="ltr" className="w-full text-center font-black tracking-wider border-2 border-teal-600 dark:bg-slate-800 rounded-xl px-4 py-4 mt-4 uppercase"/><button onClick={redeem} className="w-full bg-teal-700 text-white py-4 rounded-xl font-black mt-3">🔓 فتح الدرس الآن</button>{!user&&<p className="text-xs text-red-500 mt-2 font-bold">يجب تسجيل الدخول أولاً لاستخدام الكود</p>}<button onClick={()=>setModal("")} className="w-full text-slate-400 py-2">إغلاق ✕</button></div></div>}

      {qrCourse && <div className="fixed inset-0 z-[80] bg-black/60 grid place-items-center p-3" onClick={()=>setQrCourse(null)}><div className="bg-white rounded-3xl p-6 text-center fade-up" onClick={e=>e.stopPropagation()}><h3 className="font-black text-slate-900">{qrCourse.title}</h3><img src={`https://api.qrserver.com/v1/create-qr-code/?size=220x220&color=0f766e&data=${encodeURIComponent(typeof window!=="undefined"?location.origin+"/?course="+qrCourse.id:"")}`} alt="QR Code" className="mx-auto my-4 w-[220px] h-[220px]"/><p className="text-sm text-slate-500">امسح الكود بكاميرا الموبايل لفتح الكورس مباشرة 📱</p><button onClick={()=>setQrCourse(null)} className="mt-3 bg-slate-900 text-white px-6 py-3 rounded-xl font-bold">إغلاق</button></div></div>}
    </div>
  );
}
